import json
import re
from collections import deque
from dataclasses import dataclass
from pathlib import Path
from typing import Dict, List, Optional, Tuple


SECTION_RE = re.compile(r"^\s*\[(.+?)\]\s*$")
CHOICE_RE = re.compile(r"^\s*(\d+)\.\s*(.+)$")


@dataclass
class Node:
    node_id: str
    text: str
    speaker: str
    node_type: str


@dataclass
class Edge:
    src: str
    dst: str
    text: str


def _split_arrow(line: str) -> Tuple[str, Optional[str]]:
    if "->" not in line:
        return line.strip(), None
    left, right = line.rsplit("->", 1)
    left = left.strip()
    right = right.strip() or None
    return left, right


def _parse_line(line: str) -> Tuple[str, str, Optional[str]]:
    line_body, target = _split_arrow(line)
    speaker = ""
    text = line_body
    if ":" in line_body:
        speaker_part, _, text_part = line_body.partition(":")
        speaker = speaker_part.strip()
        text = text_part.strip()
    else:
        text = line_body.strip()
    return speaker, text, target


def parse_script(text: str) -> Dict[str, List[Dict[str, str]]]:
    nodes: Dict[str, Node] = {}
    edges: List[Edge] = []
    order: List[str] = []

    current_id: Optional[str] = None
    current_lines: List[str] = []

    def flush_section(section_id: str, lines: List[str]) -> None:
        clean_lines = [ln.strip() for ln in lines if ln.strip()]
        if not clean_lines:
            nodes[section_id] = Node(section_id, "", "", "line")
            return

        choice_lines = []
        non_choice_lines = []
        for ln in clean_lines:
            if CHOICE_RE.match(ln):
                choice_lines.append(ln)
            else:
                non_choice_lines.append(ln)

        if choice_lines:
            speaker = ""
            text = ""
            if non_choice_lines:
                speaker, text, _ = _parse_line(non_choice_lines[0])
            nodes[section_id] = Node(section_id, text, speaker, "choice")
            for ln in choice_lines:
                match = CHOICE_RE.match(ln)
                if not match:
                    continue
                choice_body = match.group(2)
                choice_text, target = _split_arrow(choice_body)
                if target:
                    edges.append(Edge(section_id, target, choice_text))
        else:
            parsed_lines = [_parse_line(ln) for ln in clean_lines]
            speakers = {speaker for speaker, _, _ in parsed_lines if speaker}
            speaker = parsed_lines[0][0] if len(speakers) <= 1 else ""
            text_parts: List[str] = []
            for spk, txt, _ in parsed_lines:
                if speaker and spk == speaker:
                    text_parts.append(txt)
                else:
                    if spk:
                        text_parts.append(f"{spk}: {txt}")
                    else:
                        text_parts.append(txt)
            text = " ".join(part for part in text_parts if part)
            nodes[section_id] = Node(section_id, text, speaker, "line")
            for _, _, target in parsed_lines:
                if target:
                    edges.append(Edge(section_id, target, ""))

    for raw_line in text.splitlines():
        line = raw_line.rstrip()
        if not line.strip():
            continue
        match = SECTION_RE.match(line)
        if match:
            if current_id is not None:
                flush_section(current_id, current_lines)
            current_id = match.group(1).strip()
            order.append(current_id)
            current_lines = []
        else:
            current_lines.append(line)

    if current_id is not None:
        flush_section(current_id, current_lines)

    if not order:
        return {"nodes": [], "edges": []}

    node_ids = set(nodes.keys())
    for edge in edges:
        if edge.dst and edge.dst not in node_ids:
            nodes[edge.dst] = Node(edge.dst, "", "", "line")
            node_ids.add(edge.dst)

    adjacency: Dict[str, List[str]] = {}
    for edge in edges:
        adjacency.setdefault(edge.src, []).append(edge.dst)

    start_id = order[0]
    reachable = set()
    queue = deque([start_id])
    while queue:
        current = queue.popleft()
        if current in reachable:
            continue
        reachable.add(current)
        for neighbor in adjacency.get(current, []):
            if neighbor and neighbor not in reachable:
                queue.append(neighbor)

    filtered_nodes = {node_id: node for node_id, node in nodes.items() if node_id in reachable}
    filtered_edges = [
        edge for edge in edges
        if edge.src in reachable and (not edge.dst or edge.dst in reachable)
    ]

    ordered_nodes: List[Node] = []
    seen = set()
    for node_id in order:
        if node_id in filtered_nodes and node_id not in seen:
            ordered_nodes.append(filtered_nodes[node_id])
            seen.add(node_id)
    for node_id in sorted(filtered_nodes.keys()):
        if node_id not in seen:
            ordered_nodes.append(filtered_nodes[node_id])
            seen.add(node_id)

    return {
        "nodes": [
            {
                "id": node.node_id,
                "text": node.text,
                "speaker": node.speaker,
                "type": node.node_type,
            }
            for node in ordered_nodes
        ],
        "edges": [
            {"from": edge.src, "to": edge.dst, "text": edge.text}
            for edge in filtered_edges
        ],
    }


def _escape_dot(value: str) -> str:
    return value.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n")


def _graph_to_dot(graph: Dict[str, List[Dict[str, str]]]) -> str:
    lines = ["digraph Dialogue {", "  rankdir=LR;"]
    for node in graph["nodes"]:
        label_parts = [node["id"]]
        if node["text"]:
            if node["speaker"]:
                label_parts.append(f"{node['speaker']}: {node['text']}")
            else:
                label_parts.append(node["text"])
        label = _escape_dot("\n".join(label_parts))
        shape = "diamond" if node["type"] == "choice" else "box"
        lines.append(f"  \"{_escape_dot(node['id'])}\" [label=\"{label}\", shape={shape}];")

    for edge in graph["edges"]:
        if edge["text"]:
            label = _escape_dot(edge["text"])
            lines.append(
                f"  \"{_escape_dot(edge['from'])}\" -> \"{_escape_dot(edge['to'])}\" [label=\"{label}\"];"
            )
        else:
            lines.append(
                f"  \"{_escape_dot(edge['from'])}\" -> \"{_escape_dot(edge['to'])}\";"
            )

    lines.append("}")
    return "\n".join(lines)


def main() -> None:
    script_path = Path("/app/script.txt")
    output_json = Path("/app/dialogue.json")
    output_dot = Path("/app/dialogue.dot")

    text = script_path.read_text(encoding="utf-8")
    graph = parse_script(text)

    output_json.write_text(json.dumps(graph, indent=2), encoding="utf-8")
    output_dot.write_text(_graph_to_dot(graph), encoding="utf-8")


if __name__ == "__main__":
    main()
